		ASSERT_THAT(AreEqual(asAST_EXPR_DECL_REF,
			Context.GetExpr(Assign->children[0])->kind));
		ASSERT_THAT(AreEqual(asAST_EXPR_INTEGER_LITERAL,
			Context.GetExpr(Assign->children[1])->kind));
