		ASSERT_THAT(IsTrue(FFileHelper::LoadFileToString(
			SemaDeclSource, *FPaths::Combine(SourceRoot, TEXT("as_sema_decl.cpp")))));
		ASSERT_THAT(IsTrue(FFileHelper::LoadFileToString(
			SemaHeaderSource, *FPaths::Combine(SourceRoot, TEXT("as_sema.h")))));

		int32 BindingCount = 0;
